var calc_output = [];

var gcs = parseFloat(gcs);
var avpu = parseFloat(avpu);
var airway = parseFloat(airway);
var neuro_deficit = parseFloat(neuro_deficit);
var ams = parseFloat(ams);
var neck_pain = parseFloat(neck_pain);
var hd_inj = parseFloat(hd_inj);

var msg;
var risk;
if (gcs == 0 || avpu == 3 || airway == 1 || neuro_deficit == 1) {
    msg = "Consider CT",
    risk = "12.1";
} else if (gcs == 1 || avpu == 1 || avpu == 2 || ams == 1 || neck_pain == 1 || hd_inj == 1) {
    msg = "Consider plain x-ray",
    risk = "2.8"
} else {
    msg = "Consider clinical clearance",
    risk = "0.2"
}

calc_output.push({
    name: 'mini',
    value: msg,
    value_text: '',
    message: risk + '% risk of c-spine injury'
});
